// Efeitos com MEMÓRIA ESTÁTICA: todos os buffers e malhas são criados na partida; o laço de animação só recicla.
// Partículas (fumaça leve, borrifo, gêiser, fogo, faíscas, chaff, bolhas), traçantes do CIWS, granadas, mísseis,
// torpedos e esteiras de espuma. Fumaça some perto da câmera e é translúcida (nunca tapa a mira).
import * as THREE from 'three';
