export const VS_PT = `attribute vec3 cor; attribute float al; attribute float tam; varying vec3 vC; varying float vA; uniform float uEsc; uniform float uPerto;
void main(){ vC = cor; vec4 mv = modelViewMatrix * vec4(position, 1.0); float dc = -mv.z; vA = al * smoothstep(uPerto, uPerto * 2.5, dc); gl_PointSize = min(tam * uEsc / max(1.0, dc), 380.0); gl_Position = projectionMatrix * mv; }`;
export const FS_PT = `uniform sampler2D uTex; varying vec3 vC; varying float vA; void main(){ vec4 t = texture2D(uTex, gl_PointCoord); gl_FragColor = vec4(vC * (0.78 + 0.22 * t.r), t.a * vA); if (gl_FragColor.a < 0.004) discard; }`;

function texPuff() { const c = document.createElement('canvas'); c.width = c.height = 64; const x = c.getContext('2d'); const g = x.createRadialGradient(32, 32, 2, 32, 32, 31); g.addColorStop(0, 'rgba(255,255,255,1)'); g.addColorStop(0.45, 'rgba(255,255,255,.55)'); g.addColorStop(1, 'rgba(255,255,255,0)'); x.fillStyle = g; x.fillRect(0, 0, 64, 64); return new THREE.CanvasTexture(c); }

const CORES = new Map();
/** v1.2.29 crit9: sobe só a faixa usada do buffer (sem alocação: 1 objeto de faixa reutilizado por atributo). Nada muda na tela. */
export function sobeFaixa(at, ini, n) { if (n <= 0) return; const R = at._fx29 || (at._fx29 = { start: 0, count: 0 }); R.start = ini; R.count = n; at.updateRanges.length = 0; at.updateRanges.push(R); at.needsUpdate = true; }
/** Sistema de partículas de tamanho fixo (anel circular de slots). */
export class Particulas {
  constructor(cena, n, aditivo, perto, tex) {
    this.n = n; this.i = 0; this.fator = 1; const A = (k) => new Float32Array(n * k);
    this.pos = A(3); this.cor = A(3); this.al = A(1); this.tam = A(1); this.vel = A(3); this.vida = A(1); this.vida0 = A(1); this.grav = A(1); this.cresce = A(1); this.a0 = A(1); this.arr = A(1);
    const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage)); g.setAttribute('cor', new THREE.BufferAttribute(this.cor, 3).setUsage(THREE.DynamicDrawUsage)); g.setAttribute('al', new THREE.BufferAttribute(this.al, 1).setUsage(THREE.DynamicDrawUsage)); g.setAttribute('tam', new THREE.BufferAttribute(this.tam, 1).setUsage(THREE.DynamicDrawUsage));
    this.mat = new THREE.ShaderMaterial({ transparent: true, depthWrite: false, blending: aditivo ? THREE.AdditiveBlending : THREE.NormalBlending, uniforms: { uEsc: { value: 600 }, uPerto: { value: perto }, uTex: { value: tex } }, vertexShader: VS_PT, fragmentShader: FS_PT });
    this.pts = new THREE.Points(g, this.mat); this.pts.frustumCulled = false; this.pts.renderOrder = aditivo ? 6 : 5; cena.add(this.pts); this.g = g; this.c = new THREE.Color(); this.ativas = 0; this._lo = n; this._hi = -1; /* v1.2.29 crit9: faixa suja (emite/passo) subida só no render da cena */ const self = this, ant = cena.onBeforeRender; cena.onBeforeRender = function (a, b, c, d) { ant.call(this, a, b, c, d); self.sobe(); };
  }
  emite(x, y, z, vx, vy, vz, cor, a, tam, vida, cresce = 1, grav = 0, arr = 0.5) {
    if (this.fator < 1 && Math.random() > this.fator) return; const i = this.i; this.i = (this.i + 1) % this.n; const k = i * 3;
    this.pos[k] = x; this.pos[k + 1] = y; this.pos[k + 2] = z; this.vel[k] = vx; this.vel[k + 1] = vy; this.vel[k + 2] = vz; let cc = CORES.get(cor); if (!cc) { this.c.set(cor); cc = [this.c.r, this.c.g, this.c.b]; CORES.set(cor, cc); } this.cor[k] = cc[0]; this.cor[k + 1] = cc[1]; this.cor[k + 2] = cc[2]; /* v1.2.1: cache de cor (sem parse de string por partícula) */
    if (i < this._lo) this._lo = i; if (i > this._hi) this._hi = i; this.a0[i] = a; this.al[i] = a; this.tam[i] = tam; this.vida[i] = this.vida0[i] = vida; this.cresce[i] = cresce; this.grav[i] = grav; this.arr[i] = arr;
  }
  passo(dt, vx = 0, vz = 0) { let n = 0; for (let i = 0; i < this.n; i++) { if (this.vida[i] <= 0) { if (this.al[i] !== 0) { this.al[i] = 0; if (i < this._lo) this._lo = i; if (i > this._hi) this._hi = i; } continue; } n++; if (i < this._lo) this._lo = i; if (i > this._hi) this._hi = i; const k = i * 3; this.vida[i] -= dt; const t = Math.max(0, this.vida[i] / this.vida0[i]); const d = 1 - this.arr[i] * dt;
      this.vel[k] = this.vel[k] * d + vx * dt * 0.3; this.vel[k + 1] = this.vel[k + 1] * d - this.grav[i] * dt; this.vel[k + 2] = this.vel[k + 2] * d + vz * dt * 0.3; this.pos[k] += this.vel[k] * dt; this.pos[k + 1] += this.vel[k + 1] * dt; this.pos[k + 2] += this.vel[k + 2] * dt;
      if (this.grav[i] > 0 && this.pos[k + 1] < 0) { this.pos[k + 1] = 0; this.vida[i] = Math.min(this.vida[i], 0.25); }
      this.tam[i] += this.cresce[i] * dt; this.al[i] = this.a0[i] * Math.min(1, t * 2.2) * (t > 0.92 ? (1 - t) / 0.08 : 1); }
    this.ativas = n; }
  sobe() { const lo = this._lo, hi = this._hi; if (hi < lo) return; const c = hi - lo + 1, a = this.g.attributes; sobeFaixa(a.position, lo * 3, c * 3); sobeFaixa(a.cor, lo * 3, c * 3); sobeFaixa(a.al, lo, c); sobeFaixa(a.tam, lo, c); this._lo = this.n; this._hi = -1; }
}

const ESTEIRA_VS = `attribute float lado; attribute float ao; varying vec2 vU; varying float vL; void main(){ vU = uv; vL = lado; vec4 w = modelMatrix * vec4(position, 1.0); gl_Position = projectionMatrix * viewMatrix * w; }`;
const ESTEIRA_FS = `uniform float uA; uniform float uT; uniform vec3 uLuz; varying vec2 vU; varying float vL;
float hs(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); } float ns(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f); return mix(mix(hs(i), hs(i + vec2(1, 0)), f.x), mix(hs(i + vec2(0, 1)), hs(i + vec2(1, 1)), f.x), f.y); }
/* v1.2.15 ESTEIRA REALISTA: água aerada (turquesa clara, translúcida) + filetes de espuma com rede de bolhas, borda irregular, duas faixas de hélice que se fundem e dissipação gradual ao longo de todo o rastro */
void main(){ float x = abs(vU.x - 0.5) * 2.0; float ao = vU.y;
  float bn = ns(vec2(vU.y * 23.0 - uT * 0.4, vU.x * 3.0)) - 0.5; float borda = smoothstep(1.0, 0.5 + 0.18 * bn, x); /* borda irregular */
  float sep = mix(0.34, 0.0, smoothstep(0.04, 0.34, ao)); float larg = mix(0.14, 0.5, smoothstep(0.0, 0.55, ao)); float faixas = smoothstep(larg, 0.0, abs(x - sep));
  float vida = pow(1.0 - ao, 1.35) * smoothstep(0.0, 0.025, ao); /* dissipa aos poucos */
  float t1 = ns(vec2(vU.x * 9.0, vU.y * 26.0 - uT * 1.2)), t2 = ns(vec2(vU.x * 27.0 + t1 * 2.0, vU.y * 80.0 - uT * 2.1)), t3 = ns(vec2(vU.x * 61.0, vU.y * 190.0 - uT * 2.9));
  float turb = t1 * 0.55 + t2 * 0.33 + t3 * 0.12; /* turbulência com textura (filetes alongados no sentido do rastro) */
  float k = vida * (0.45 + 0.55 * faixas); float cel = abs(t2 - 0.5) * 1.4 + abs(t3 - 0.5) * 0.8; float bolhas = smoothstep(1.05 - k, 1.4 - k * 0.7, cel + turb * 0.6 + k * 0.4);
  float espuma = borda * bolhas * smoothstep(0.25, 0.65, turb + 0.35 * k) * (0.35 + 0.65 * k);
  float aerada = borda * vida * (0.32 + 0.4 * faixas) * (0.7 + 0.3 * turb);
  vec3 cA = vec3(0.36, 0.58, 0.6), cE = vec3(0.88, 0.92, 0.94) * (0.86 + 0.14 * t3); float a = clamp(aerada * 0.55 + espuma * 1.1, 0.0, 0.92);
  vec3 cor = mix(cA, cE, clamp(espuma * 1.6 / max(a, 1e-3), 0.0, 1.0)); cor *= uLuz; /* v1.2.18 item 4: sem brilho próprio (era neon ao entardecer/noite) */ gl_FragColor = vec4(cor, a * uA); if (gl_FragColor.a < 0.01) discard; }`;

